{
  "units": [
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "To receive a grant or allotment under section 9905 or 9906 of this title, the chief executive officer of a State must designate an appropriate State agency that complies with the duties specified in paragraph (2) to act as the lead agency for carrying out State activities under this chapter, designating it in an application submitted to the Secretary under subsection (b)."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "The designated State lead agency must develop the State plan to be submitted to the Secretary under subsection (b)."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "In conjunction with developing the State plan under subsection (b), the designated State lead agency must hold at least one hearing in the State with sufficient time and statewide distribution of notice, giving the public an opportunity to comment on the proposed use and distribution of funds provided through the grant or allotment under section 9905 or 9906 for the period covered by the State plan."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "The designated State lead agency must conduct reviews of eligible entities under section 9914 of this title."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "In order to be eligible to receive a grant or allotment under section 9905 or 9906 of this title, the State must hold at least one legislative hearing every 3 years in conjunction with the development of the State plan."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Beginning with fiscal year 2000, to be eligible to receive a grant or allotment under section 9905 or 9906 of this title, a State must prepare and submit to the Secretary an application and State plan covering a period of not less than 1 fiscal year and not more than 2 fiscal years, submitted not later than 30 days prior to the beginning of the first fiscal year covered by the plan, containing such information as the Secretary requires, including paragraphs (1) through (13)."
    },
    {
      "quote_ref": "F015:F016",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "The State application and plan must contain an assurance that grant or allotment funds will be used to support activities designed to assist low-income families and individuals (including those receiving TANF assistance under part A of title IV of the Social Security Act, homeless families and individuals, migrant or seasonal farmworkers, and elderly low-income individuals and families), and a description of how such activities will enable them to remove obstacles and solve problems that block self-sufficiency (including transitioning off a State part A title IV program)."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The State plan must include a description of how supported activities will enable low-income families and individuals to secure and retain meaningful employment."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The State plan must include a description of how supported activities will enable low-income families and individuals to attain an adequate education, with particular attention toward improving literacy skills of low-income families in the communities involved, which may include carrying out family literacy initiatives."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The State plan must include a description of how supported activities will enable low-income families and individuals to make better use of available income."
    },
    {
      "quote_ref": "F020",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The State plan must include a description of how supported activities will enable low-income families and individuals to obtain and maintain adequate housing and a suitable living environment."
    },
    {
      "quote_ref": "F021",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The State plan must include a description of how supported activities will enable low-income families and individuals to obtain emergency assistance through loans, grants, or other means to meet immediate and urgent family and individual needs."
    },
    {
      "quote_ref": "F022:F024",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The State plan must include a description of how supported activities will enable low-income families and individuals to achieve greater participation in community affairs, including developing public and private grassroots partnerships with local law enforcement, housing authorities, private foundations, and others to document urban grassroots best practices for widespread replication, and to strengthen relationships with local law enforcement (which may include neighborhood or community policing efforts)."
    },
    {
      "quote_ref": "F026:F028",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that funds will be used to address youth needs in low-income communities through youth development programs that support the family's primary role, prioritize prevention of youth problems and crime, promote community coordination and collaboration, and support innovative community-based youth programs demonstrated to reduce youth crime, such as violence-free zones with intervention models (mediation, mentoring, life skills, job creation, entrepreneurship) and after-school child care programs."
    },
    {
      "quote_ref": "F029",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that grant or allotment funds will be used to make more effective use of, and coordinate with, other programs related to the purposes of this chapter, including State welfare reform efforts."
    },
    {
      "quote_ref": "F031",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain a description of how the State intends to use discretionary funds from the remainder of the grant or allotment under section 9907(b) in accordance with this chapter, including how it will support innovative community- and neighborhood-based initiatives related to chapter purposes."
    },
    {
      "quote_ref": "F033",
      "scope_refs": ["F013", "F032"],
      "kind": "requirement",
      "meaning": "The State plan must include information provided by eligible entities in the State describing the service delivery system for services provided or coordinated with section 9907(a) funds targeted to low-income individuals and families."
    },
    {
      "quote_ref": "F034",
      "scope_refs": ["F013", "F032"],
      "kind": "requirement",
      "meaning": "The State plan must include information provided by eligible entities describing how linkages will be developed to fill identified service gaps through information, referrals, case management, and followup consultations."
    },
    {
      "quote_ref": "F035",
      "scope_refs": ["F013", "F032"],
      "kind": "requirement",
      "meaning": "The State plan must include information provided by eligible entities describing how section 9907(a) grant funds will be coordinated with other public and private resources."
    },
    {
      "quote_ref": "F036",
      "scope_refs": ["F013", "F032"],
      "kind": "requirement",
      "meaning": "The State plan must include information provided by eligible entities describing how the local entity will use funds to support innovative community- and neighborhood-based initiatives related to chapter purposes, which may include fatherhood initiatives and other family-strengthening and parenting initiatives."
    },
    {
      "quote_ref": "F038",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that eligible entities in the State will provide, on an emergency basis, supplies, services, nutritious foods, and related services necessary to counteract starvation and malnutrition among low-income individuals."
    },
    {
      "quote_ref": "F039",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State and eligible entities will coordinate and establish linkages between governmental and other social services programs to assure effective delivery and avoid duplication, as well as a description of how they will coordinate employment and training activities (as defined under section 3 of WIOA) with entities providing activities through statewide and local workforce development systems under WIOA."
    },
    {
      "quote_ref": "F040",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State will ensure coordination between antipoverty programs in each community, and ensure, where appropriate, that emergency energy crisis intervention programs under title XXVI (LIHEAP) are conducted in that community."
    },
    {
      "quote_ref": "F041",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State will permit and cooperate with Federal investigations undertaken pursuant to section 9916 of this title."
    },
    {
      "quote_ref": "F042",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that any eligible entity that received CSBG funding in the previous fiscal year will not have its funding terminated or reduced below its previous year proportional share unless, after notice and opportunity for a hearing on the record, the State determines that cause exists, subject to review by the Secretary under section 9915(b)."
    },
    {
      "quote_ref": "F043",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State and eligible entities will, to the maximum extent possible, coordinate programs and form partnerships with other organizations serving low-income residents, including religious organizations, charitable groups, and community organizations."
    },
    {
      "quote_ref": "F044",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State will require each eligible entity to establish procedures allowing a low-income individual, community organization, religious organization, or representative of low-income individuals who considers their organization or low-income individuals inadequately represented on the entity's board (or other mechanism) to petition for adequate representation."
    },
    {
      "quote_ref": "F045",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State will secure from each eligible entity, as a condition of receiving CSBG funding, a community action plan that includes a community-needs assessment (which may be coordinated with other assessments), and must submit that community action plan to the Secretary upon request with the State plan."
    },
    {
      "quote_ref": "F046",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State and all eligible entities will participate, not later than fiscal year 2001, in the Results Oriented Management and Accountability System (ROMA), another performance measurement system facilitated by the Secretary under section 9917(b), or an alternative qualifying system, and must contain a description of outcome measures used to measure entity performance in promoting self-sufficiency, family stability, and community revitalization."
    },
    {
      "quote_ref": "F047",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain information describing how the State will carry out each of the assurances described in subsection (b)."
    },
    {
      "quote_ref": "F051:F054",
      "scope_refs": ["F049", "F050"],
      "kind": "definition",
      "meaning": "For purposes of making a funding reduction determination under subsection (b)(8), 'cause' includes a statewide redistribution of CSBG funds to respond to the results of the most recently available census or other appropriate data, the designation of a new eligible entity, or severe economic dislocation."
    },
    {
      "quote_ref": "F055",
      "scope_refs": ["F049", "F050"],
      "kind": "definition",
      "meaning": "For purposes of making a funding reduction determination under subsection (b)(8), 'cause' includes the failure of an eligible entity to comply with the terms of an agreement or State plan, or to meet a State requirement, as described in section 9915(a) of this title."
    },
    {
      "quote_ref": "F057",
      "scope_refs": ["F049"],
      "kind": "definition",
      "meaning": "For purposes of making a funding termination determination under subsection (b)(8), 'cause' includes the failure of an eligible entity to comply with the terms of an agreement or State plan, or to meet a State requirement, as described in section 9915(a) of this title."
    },
    {
      "quote_ref": "F060",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The Secretary is authorized to prescribe procedures for the purpose of assessing the effectiveness of eligible entities in carrying out the purposes of this chapter."
    },
    {
      "quote_ref": "F064",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The chief executive officer of each State is permitted to revise any plan prepared under section 9908 and must submit any such revised plan to the Secretary."
    },
    {
      "quote_ref": "F067",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Each plan or revised plan prepared under section 9908 must be made available for public inspection within the State in a manner that facilitates review of, and comment on, the plan."
    },
    {
      "quote_ref": "F070",
      "scope_refs": [],
      "kind": "exception",
      "meaning": "For fiscal year 2000, to be eligible to receive a grant or allotment under section 9905 or 9906, a State must prepare and submit to the Secretary an application and State plan in accordance with the provisions of this chapter as in effect on October 26, 1998, rather than conforming to subsections (a) through (c)."
    },
    {
      "quote_ref": "F071",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Public law citation and enactment history for section 9908, containing no ongoing operative duties or rights."
    },
    {
      "quote_ref": "F074:F076",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial statutory cross-references detailing the codification locations of the Social Security Act, Workforce Innovation and Opportunity Act, and Low-Income Home Energy Assistance Act of 1981."
    },
    {
      "quote_ref": "F078:F079",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial notes identifying prior sections 9908 and 676 of Pub. L. 97-35 prior to the general amendment by Pub. L. 105-285."
    },
    {
      "quote_ref": "F081",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial note detailing the 2014 amendment text substitution in subsection (b)(5)."
    },
    {
      "quote_ref": "F084",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "The amendment made by Pub. L. 113-128 took effect on the first day of the first full program year after July 22, 2014 (July 1, 2015)."
    }
  ]
}
